insert into scenarios (id, slug, title, sector, difficulty, summary, description, image_key, is_published, sort_order) values ('c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'city-centre-tower', 'City-Centre Office Tower', 'Commercial', 'advanced', 'A 14-storey office tower on a tight city-centre plot bounded by public footways, a busy road and a neighbouring occupied building.', 'You are the principal contractor''s site manager mobilising a constrained urban site. The basement requires deep excavation against existing party walls, a tower crane will oversail the public highway, and pedestrian footfall around the hoarding line is heavy. Decisions must protect the public as well as the workforce.', 'tower', true, 0);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('5d0fb227-61d5-5958-953a-c98e8b2ef562', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'mobilisation', 'Site Mobilisation, Welfare & Security', 'Pre-construction / Set-up', 'Establish compliant welfare facilities and a secure site boundary in line with CDM 2015 Schedule 2 and the principal contractor''s duties.', 'The plot opens directly onto a public footway. How do you set up the boundary and welfare before works start?', 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('98c022ba-8491-557d-9dd1-fb65a27d93fa', '5d0fb227-61d5-5958-953a-c98e8b2ef562', 'Erect solid hoarding to the footway line with managed gates, and install heated welfare units (toilets, drying room, canteen) sized for peak workforce', 'Protects the public and provides compliant welfare from day one.', 'Meets CDM 2015 Schedule 2 welfare duties and protects non-workers under the principal contractor''s duties.', 'On a public-facing urban site, solid hoarding is required to protect passers-by, and welfare must be available before work begins, not retro-fitted.', 10, -12, true, '{"add":["hoarding","security_gate","welfare_unit","site_office","cctv"],"note":"Secure public-facing boundary with full welfare."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('fca97893-59f1-5993-97da-8127e8802e64', '5d0fb227-61d5-5958-953a-c98e8b2ef562', 'Put up Heras mesh fencing and bring a single portable toilet, adding more welfare once the team grows', 'Basic separation but mesh is easily breached and welfare is inadequate.', 'Partially compliant — welfare provision falls short of Schedule 2 for the planned numbers.', 'Temporary fencing rarely suffices on a busy public frontage and welfare must match the actual workforce, not be scaled up reactively.', 5, -3, false, '{"add":["heras_fencing","welfare_unit"],"note":"Weak boundary, minimal welfare."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('92c622ef-f293-51da-bb6d-17d53a752c89', '5d0fb227-61d5-5958-953a-c98e8b2ef562', 'Start groundworks immediately and arrange fencing and welfare in the first fortnight', 'Leaves the public exposed to site hazards and workers without facilities.', 'Breaches CDM 2015 — welfare and public protection must be in place from the outset.', 'Beginning work without a secure boundary or welfare is a serious breach and a common cause of enforcement action.', -3, 12, false, '{"add":[],"note":"No boundary or welfare in place."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('647f2565-89e3-5248-85cc-fd8694792de3', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'logistics', 'Site Logistics & Traffic Management', 'Set-up', 'Segregate vehicles from pedestrians and plan safe access, egress and deliveries (HSG144 principles).', 'Deliveries arrive off a busy road and the public walks past the gate. How do you manage traffic and pedestrians?', 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('9f90e8a9-634f-5a35-b20e-866edce79fb0', '647f2565-89e3-5248-85cc-fd8694792de3', 'Implement a gate-booking system, a banksman/traffic marshal, segregated pedestrian routes and a wheel-wash, with a one-way internal flow', 'Eliminates uncontrolled vehicle/pedestrian conflict at the interface.', 'Aligns with HSG144 and CDM 2015 traffic management duties.', 'Booked deliveries, marshalling and physical segregation are the recognised controls where site traffic meets the public.', 10, -12, true, '{"add":["vehicle_route","pedestrian_route","banksman","wheel_wash","one_way_system","signage"],"note":"Segregated, marshalled logistics."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('8b15b29b-1c5c-57f8-aa10-aed50b7c2e14', '647f2565-89e3-5248-85cc-fd8694792de3', 'Post warning signage and ask drivers to sound the horn when reversing across the footway', 'Raises awareness but relies on behaviour rather than separation.', 'Falls short — reliance on signage alone is low in the hierarchy of control.', 'Signage supports but cannot replace physical segregation and marshalling at a public interface.', 5, -3, false, '{"add":["signage","vehicle_route"],"note":"Signage only; no segregation."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('eb374b8e-5724-501f-80c1-819b3fa7ec28', '647f2565-89e3-5248-85cc-fd8694792de3', 'Let deliveries arrive ad-hoc and reverse off the road when there is a gap in pedestrians', 'High risk of striking pedestrians during uncontrolled reversing.', 'Breaches traffic management duties; reversing is a leading cause of site fatalities.', 'Uncontrolled reversing across a public footway is one of the most dangerous activities on an urban site.', -3, 12, false, '{"add":["vehicle_route"],"note":"Uncontrolled reversing."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('16a3dee8-c802-5176-a098-a4da14bf7908', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'groundworks', 'Excavations & Temporary Works', 'Substructure', 'Prevent excavation collapse and control temporary works under BS 5975 with a Temporary Works Coordinator.', 'The basement needs a 6 m deep excavation next to an occupied neighbouring building. How do you proceed?', 2);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('4a1e4751-bc72-54c6-82ca-8bdff5341832', '16a3dee8-c802-5176-a098-a4da14bf7908', 'Appoint a Temporary Works Coordinator, install a designed propped retaining system with a permit-to-dig and daily inspections by a competent person', 'Prevents collapse and protects the adjacent structure.', 'Meets BS 5975 and CDM 2015; the TWC owns the temporary works register.', 'Deep excavation beside occupied structures demands designed support, a TWC and inspection before each shift.', 10, -12, true, '{"add":["excavation_support","dewatering","exclusion_zone","signage"],"note":"Designed, propped, inspected excavation."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('5e93cf1a-9cfe-5134-b1c0-a5dd6e0fc011', '16a3dee8-c802-5176-a098-a4da14bf7908', 'Batter the excavation back where space allows and use a trench box for the deeper sections', 'Reasonable for open ground but battering is not feasible against the boundary.', 'Partially compliant — needs design verification next to the neighbour.', 'Battering and trench boxes suit open excavations but a constrained deep dig against a party wall needs an engineered solution.', 5, -3, false, '{"add":["trench_box","exclusion_zone"],"note":"Trench box; no full temporary works design."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('fe4ce5cf-82ca-59b3-8731-1e63d8aaabe6', '16a3dee8-c802-5176-a098-a4da14bf7908', 'Dig the basement with vertical faces and shore only if the ground starts to move', 'Very high collapse risk and threatens the neighbouring building.', 'Serious breach of CDM 2015 and BS 5975 — excavations must be supported in advance.', 'Waiting for signs of movement is too late; excavation collapses are sudden and frequently fatal.', -3, 12, false, '{"add":[],"note":"Unsupported deep excavation."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('c01a28a2-e68a-5959-83c9-c4c643ccce2a', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'height', 'Work at Height & Access', 'Superstructure', 'Select and control safe access for work at height following the Work at Height Regulations 2005 hierarchy.', 'The frame rises 14 storeys with façade works over the public footway. How is work at height accessed and protected?', 3);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('8b9fc0fa-f85a-5681-a5fb-a9fbd7895833', 'c01a28a2-e68a-5959-83c9-c4c643ccce2a', 'Erect a designed, independently-tied scaffold with double guardrails, toes boards, brick guards and a protected pavement gantry, inspected weekly and tagged', 'Collective protection for workers and the public below.', 'Meets WAHR 2005 hierarchy, TG20/SG4 and statutory 7-day scaffold inspection.', 'Collective edge protection plus public protection (gantry/fans) is the correct top-of-hierarchy solution for tall public-facing façades.', 10, -12, true, '{"add":["scaffold","edge_protection","signage","exclusion_zone"],"note":"Tied scaffold with public gantry."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('7d23d37a-3f04-5143-afb1-7349a27f8cf9', 'c01a28a2-e68a-5959-83c9-c4c643ccce2a', 'Use MEWPs for the façade and harnesses clipped to the basket for higher lifts', 'Workable but exposes the footway and depends on rescue planning.', 'Acceptable with controls but lower in the hierarchy than collective protection.', 'MEWPs are valid but for a full tall façade over the public, scaffold with collective protection is preferable.', 5, -3, false, '{"add":["mewp","exclusion_zone"],"note":"MEWP access; PPE-reliant."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('f41c72af-19e7-53a6-b920-cc152b5e4d7b', 'c01a28a2-e68a-5959-83c9-c4c643ccce2a', 'Have operatives work off ladders and step-platforms and clip a lanyard where they can', 'Falls from height risk for workers and dropped-object risk to the public.', 'Breaches WAHR 2005 — ladders are not suitable for sustained façade work.', 'Ladders for prolonged work at height are a primary cause of fall fatalities and are top of HSE''s enforcement list.', -3, 12, false, '{"add":[],"note":"Ladder access; no collective protection."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('0b56515a-afa8-5c83-979c-af9e55f6601c', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'lifting', 'Lifting Operations & Plant', 'Superstructure', 'Plan and supervise lifting operations under LOLER 1998 / PUWER 1998 with a competent Appointed Person.', 'A tower crane will oversail the public highway to feed the build. How is the lifting operation controlled?', 4);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('00f6e99c-530c-5326-99c2-57b6bba928e8', '0b56515a-afa8-5c83-979c-af9e55f6601c', 'Appoint a competent Appointed Person, produce a lift plan, fit anti-collision/zoning to prevent oversailing the public when loaded, and use slinger/signallers', 'Removes the risk of loads passing over the public.', 'Meets LOLER 1998 and BS 7121; oversailing agreements and zoning are in place.', 'An Appointed Person, a written lift plan and load-zoning are mandatory where a crane interfaces with the public.', 10, -12, true, '{"add":["tower_crane","exclusion_zone","banksman","signage"],"note":"Planned lifts with load zoning."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('9d12978f-5e6c-542d-bdfb-a3016f6f3d47', '0b56515a-afa8-5c83-979c-af9e55f6601c', 'Use the crane with experienced operators and stop lifts manually when people are below', 'Relies on vigilance rather than engineered zoning.', 'Partially compliant — a documented lift plan and AP are still required.', 'Manual stopping is a weak control compared with anti-collision zoning and a formal lift plan.', 5, -3, false, '{"add":["tower_crane","exclusion_zone"],"note":"Crane without formal zoning."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a0f37deb-5124-56cc-878e-805257660ce2', '0b56515a-afa8-5c83-979c-af9e55f6601c', 'Run lifts as needed and rely on the operator to judge when it is safe to swing over the road', 'Loads over the public risk fatal dropped-object incidents.', 'Serious breach of LOLER and BS 7121; lifting must be planned by a competent person.', 'Unplanned lifting over the public is among the highest-consequence failures on a city site.', -3, 12, false, '{"add":["tower_crane"],"note":"Unplanned lifting over the public."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('42d73f71-5020-56cb-8327-fd181e01e80f', 'c57a7aec-e65a-5291-89c9-7cb8f066bd50', 'systems', 'Safe Systems: RAMS, Permits, ITPs & Emergency Planning', 'Throughout construction', 'Implement risk assessments and method statements, permits-to-work, inspection & test plans and emergency arrangements.', 'How will you run safe systems of work, inspections and emergencies across the project?', 5);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('181ee135-37d7-5b0e-b7b4-e5a448f8404f', '42d73f71-5020-56cb-8327-fd181e01e80f', 'Brief task-specific RAMS, operate permits-to-work for high-risk tasks, maintain an ITP for quality holds, and rehearse an emergency/rescue plan with marked fire points and first aid', 'Controls are matched to each task and emergencies are planned for.', 'Meets CDM 2015, MHSWR 1999 and first-aid/fire duties.', 'RAMS, permits, ITPs and a tested emergency plan together form the project''s safe system of work.', 10, -12, true, '{"add":["fire_point","first_aid","signage"],"note":"Full RAMS / permits / ITP / emergency regime."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('28a872f7-d11a-5226-850a-14eebae80094', '42d73f71-5020-56cb-8327-fd181e01e80f', 'Hold a generic site induction and a single overarching method statement covering all activities', 'Provides a baseline but misses task-specific high-risk controls.', 'Partially compliant — RAMS must be specific to the activity and place.', 'Generic documents do not control specific high-risk tasks; permits and task RAMS are needed.', 5, -3, false, '{"add":["first_aid"],"note":"Generic method statement only."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('365b76c4-9972-5397-94ad-1b1c353503f9', '42d73f71-5020-56cb-8327-fd181e01e80f', 'Rely on experienced operatives to work safely and deal with incidents if they arise', 'No structured control or emergency preparedness.', 'Breaches CDM 2015 and MHSWR — risk assessment is a legal duty.', 'Experience is not a substitute for documented, communicated safe systems and emergency planning.', -3, 12, false, '{"add":[],"note":"No formal safe systems."}'::jsonb, 2);
insert into scenarios (id, slug, title, sector, difficulty, summary, description, image_key, is_published, sort_order) values ('e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'motorway-bridge', 'Motorway Bridge Replacement', 'Highways', 'advanced', 'Replacing an overbridge above a live motorway, working within night-time possessions with heavy beam lifts and traffic management.', 'You are managing a highways scheme to demolish and replace an overbridge spanning a live three-lane motorway. Work happens largely at night under traffic management, with abnormal-load deliveries and tandem crane lifts of bridge beams. Worker safety, road-user safety and possession discipline all matter.', 'bridge', true, 1);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('5fbc85fc-e547-5a7c-bd6d-c71a6c1c5192', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'mobilisation', 'Site Mobilisation, Welfare & Security', 'Pre-construction / Set-up', 'Establish compliant welfare facilities and a secure site boundary in line with CDM 2015 Schedule 2 and the principal contractor''s duties.', 'A compound is needed beside the carriageway for night works. How do you set up welfare and security?', 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('afa7cfce-3f4a-55bc-965f-e3dd693a2082', '5fbc85fc-e547-5a7c-bd6d-c71a6c1c5192', 'Establish a fenced compound set back behind safety barrier, with lit welfare cabins, drying rooms and secure plant storage suitable for night-shift numbers', 'Keeps the workforce clear of live traffic and supports night working.', 'Meets CDM 2015 Schedule 2 and roadworks safety guidance.', 'Night highway works require a properly set-back, lit and secure compound with full welfare for shift workers.', 10, -12, true, '{"add":["hoarding","security_gate","welfare_unit","site_office","material_storage"],"note":"Set-back lit compound with welfare."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('c6c774b0-c6a7-57e1-ab93-5854356b3443', '5fbc85fc-e547-5a7c-bd6d-c71a6c1c5192', 'Place welfare cabins on the verge close to the works with cone separation from traffic', 'Welfare is provided but proximity to live traffic adds risk.', 'Partially compliant — separation from live lanes is inadequate.', 'Cones are not a vehicle-restraint system; welfare should sit behind hardened protection.', 5, -3, false, '{"add":["welfare_unit","signage"],"note":"Verge-side welfare, cone separation."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('43ea878b-ecd6-5786-ace6-3764d8d00cd2', '5fbc85fc-e547-5a7c-bd6d-c71a6c1c5192', 'Use the existing layby with no dedicated welfare for the first shifts', 'Workforce exposed to traffic with no facilities.', 'Breaches CDM 2015 welfare duties.', 'Operating night shifts without compliant, protected welfare is unacceptable and unsafe.', -3, 12, false, '{"add":[],"note":"No compound or welfare."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('760d1242-9a4c-542e-8514-431973407f0e', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'logistics', 'Site Logistics & Traffic Management', 'Set-up', 'Segregate vehicles from pedestrians and plan safe access, egress and deliveries (HSG144 principles).', 'Live traffic runs beneath and beside the works. How do you manage traffic and protect the workforce?', 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('350f075a-43bd-5408-9611-8b74574141f4', '760d1242-9a4c-542e-8514-431973407f0e', 'Install a designed temporary traffic management scheme (lane closures, TTRO, hardened barrier between works and live lanes) with safety-zone widths to Chapter 8', 'Physically separates the workforce from live traffic.', 'Complies with the Traffic Signs Manual Chapter 8 and a Temporary Traffic Regulation Order.', 'Hardened barriers and correct safety zones are the recognised controls for working adjacent to live high-speed traffic.', 10, -12, true, '{"add":["vehicle_route","edge_protection","signage","exclusion_zone"],"note":"Chapter 8 TM with hardened barrier."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('78f192d5-b31e-52dc-a9ae-1403bca8a7cf', '760d1242-9a4c-542e-8514-431973407f0e', 'Use cones and chevron signs to close off a working lane with a speed-limit request', 'Provides demarcation but no physical restraint from errant vehicles.', 'Partially compliant — high-speed works need barrier protection, not cones alone.', 'Cones channel traffic but will not stop an incursion; barrier protection is needed at motorway speeds.', 5, -3, false, '{"add":["vehicle_route","signage"],"note":"Cones only; no barrier."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('44178fd0-d1bd-5684-b650-c5bf706d17f1', '760d1242-9a4c-542e-8514-431973407f0e', 'Keep all lanes running and ask the team to work quickly between traffic gaps', 'Extreme risk of operatives being struck by live traffic.', 'Serious breach of traffic management and CDM duties.', 'Working in or beside live high-speed lanes without closure or protection is potentially fatal.', -3, 12, false, '{"add":[],"note":"No traffic management."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('ac238bf6-a2a0-5a72-841c-9d89089dbd74', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'groundworks', 'Excavations & Temporary Works', 'Substructure', 'Prevent excavation collapse and control temporary works under BS 5975 with a Temporary Works Coordinator.', 'New bridge abutments require excavation and piling close to the carriageway. How is this controlled?', 2);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('ab8bc83e-0148-5191-b535-62dcbe28c9c2', 'ac238bf6-a2a0-5a72-841c-9d89089dbd74', 'Appoint a TWC, use designed shoring/casings to BS 5975, a permit-to-dig with services located (CAT scan/GPR), and exclusion zones around piling rigs', 'Prevents collapse and strikes on buried services and plant.', 'Meets BS 5975, CDM 2015 and HSG47 (avoiding underground services).', 'Excavation/piling beside a carriageway needs designed support, service location and rig exclusion zones.', 10, -12, true, '{"add":["excavation_support","exclusion_zone","signage","dewatering"],"note":"Designed support with service location."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('773932d1-eee1-5e06-b156-02fb96e6c53b', 'ac238bf6-a2a0-5a72-841c-9d89089dbd74', 'Locate services from existing drawings and batter the excavation where the verge allows', 'Some control but drawings are often inaccurate and battering is space-limited.', 'Partially compliant — HSG47 expects on-site detection, not drawings alone.', 'Record drawings must be verified on site; battering may not fit beside the carriageway.', 5, -3, false, '{"add":["trench_box","exclusion_zone"],"note":"Drawings only; partial support."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('46155fed-7a1a-5368-bfa2-64c66111aff9', 'ac238bf6-a2a0-5a72-841c-9d89089dbd74', 'Excavate to vertical faces and keep the piling rig working close to the open edge', 'Collapse and rig-overturn risk near the carriageway.', 'Breaches BS 5975 and CDM 2015.', 'Unsupported faces and rigs at the edge of excavations are a recognised cause of collapses and overturns.', -3, 12, false, '{"add":[],"note":"Unsupported excavation by carriageway."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('8b9e6f23-494c-5b13-bd3a-cce486f384d4', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'height', 'Work at Height & Access', 'Superstructure', 'Select and control safe access for work at height following the Work at Height Regulations 2005 hierarchy.', 'Demolition and deck works occur above the live (or possessed) carriageway. How do you protect against falls and debris?', 3);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('cad5359c-8645-5075-97b7-09943c3fc5a2', '8b9e6f23-494c-5b13-bd3a-cce486f384d4', 'Use a fully boarded, netted and fanned access with debris containment over the carriageway, mobile elevating platforms with rescue plans, and a possession before any over-road work', 'Protects workers from falls and the road from falling debris.', 'Meets WAHR 2005 and possession rules; debris netting protects road users.', 'Over-road work requires collective fall protection plus debris containment and is only done within a possession.', 10, -12, true, '{"add":["scaffold","edge_protection","exclusion_zone","signage"],"note":"Netted/fanned access within possession."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('38dc9c1b-18d9-561f-b0d5-9841b2d2119b', '8b9e6f23-494c-5b13-bd3a-cce486f384d4', 'Provide harnesses and nets and allow over-road work with a lane closed beneath', 'Reduces consequences but relies partly on PPE.', 'Acceptable with controls but collective debris protection is preferred.', 'Closing the lane below helps, but collective protection and containment should lead over PPE.', 5, -3, false, '{"add":["edge_protection","exclusion_zone"],"note":"PPE-reliant over-road work."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a42f3a01-6b36-5441-8e9e-9d2e004f5e87', '8b9e6f23-494c-5b13-bd3a-cce486f384d4', 'Let the team remove the deck over running traffic during quiet periods', 'Falling debris and falls of persons onto live traffic.', 'Serious breach of WAHR 2005 and possession discipline.', 'Demolition over live traffic is one of the highest-risk activities and must never proceed without a possession and containment.', -3, 12, false, '{"add":[],"note":"Over-road demolition, no protection."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('936d47be-a143-5450-9c43-dfa806142a26', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'lifting', 'Lifting Operations & Plant', 'Superstructure', 'Plan and supervise lifting operations under LOLER 1998 / PUWER 1998 with a competent Appointed Person.', 'Bridge beams must be lifted in within a short night possession. How is the lift planned?', 4);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('395f265d-a1a7-58cd-afee-bc015094768a', '936d47be-a143-5450-9c43-dfa806142a26', 'Appoint an Appointed Person, produce a contract lift / tandem-lift plan, validate ground bearing and crane pads, set exclusion zones and rehearse the sequence within the possession window', 'Controls the heavy lift and keeps everyone clear.', 'Meets LOLER 1998 and BS 7121 for tandem and contract lifts.', 'Heavy beam lifts demand an AP, a detailed plan, verified ground conditions and rehearsed timing within the possession.', 10, -12, true, '{"add":["mobile_crane","exclusion_zone","banksman","signage"],"note":"Planned tandem lift with exclusion zones."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('9d02e210-a6da-5335-ab5a-9e2fbfafadf9', '936d47be-a143-5450-9c43-dfa806142a26', 'Use an experienced crane crew with a basic lift plan and outrigger mats', 'Competent crew but the plan lacks tandem-lift and ground detail.', 'Partially compliant for a complex tandem lift.', 'Complex tandem lifts need more than a basic plan — ground bearing and synchronised control are critical.', 5, -3, false, '{"add":["mobile_crane","exclusion_zone"],"note":"Basic plan; limited detail."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('1b9e2200-f817-52ec-97f6-8442a9753018', '936d47be-a143-5450-9c43-dfa806142a26', 'Bring the cranes on the night and work out the lift sequence on site to save planning time', 'High risk of overturn or dropped beam over the carriageway.', 'Serious breach of LOLER/BS 7121.', 'Improvised heavy lifts over a motorway are extremely dangerous and indefensible.', -3, 12, false, '{"add":["mobile_crane"],"note":"Unplanned heavy lift."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('02c5a3dd-c754-518d-9ed8-4e93b378403c', 'e05e7b7c-7edf-5439-b00e-36a1fed3cd4d', 'systems', 'Safe Systems: RAMS, Permits, ITPs & Emergency Planning', 'Throughout construction', 'Implement risk assessments and method statements, permits-to-work, inspection & test plans and emergency arrangements.', 'How will you run safe systems, possession control and emergencies for night working?', 5);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('287f010b-aac9-5fe4-91c7-62b8d1970342', '02c5a3dd-c754-518d-9ed8-4e93b378403c', 'Operate task RAMS, permits for hot works/lifting/over-road work, an ITP for the new deck, possession sign-on/off, and an emergency plan including incursion and casualty rescue', 'Controls each high-risk task and prepares for incursions and casualties.', 'Meets CDM 2015, possession rules and emergency planning duties.', 'Night highway works need permits, possession discipline, ITPs and a tested incursion/rescue plan.', 10, -12, true, '{"add":["fire_point","first_aid","signage"],"note":"Permits, ITP and incursion plan."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('6b34d322-836c-5320-bc28-90f17f6809c3', '02c5a3dd-c754-518d-9ed8-4e93b378403c', 'Use a standard induction and rely on the TM contractor to manage possessions', 'Baseline only; task-specific and incursion controls are thin.', 'Partially compliant — the PC retains responsibility for safe systems.', 'The principal contractor cannot delegate away its duty to operate task-specific safe systems.', 5, -3, false, '{"add":["first_aid"],"note":"Generic systems; delegated TM."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('54775ef2-d606-5d6f-a31a-9f4419a0a077', '02c5a3dd-c754-518d-9ed8-4e93b378403c', 'Keep paperwork light to maximise productive time in the possession', 'No structured control of high-risk night tasks.', 'Breaches CDM 2015 and MHSWR.', 'Cutting safe-system documentation to save time directly increases the chance of a serious incident.', -3, 12, false, '{"add":[],"note":"Minimal safe systems."}'::jsonb, 2);
insert into scenarios (id, slug, title, sector, difficulty, summary, description, image_key, is_published, sort_order) values ('702a4014-c2a4-52c2-b59b-52002271d147', 'primary-school', 'New Primary School', 'Education', 'intermediate', 'Building a new primary school on land adjacent to an occupied, operating school — safeguarding and segregation are paramount.', 'You are mobilising a new-build primary school next to a school that remains open throughout. Children, parents and staff are present daily. The build involves groundworks, a steel and timber frame, and roof works, with shared access near the existing school gate. Safeguarding and total segregation of the public drive the safety strategy.', 'school', true, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('6cf91fa9-b4b7-5524-9764-62889d5d79d9', '702a4014-c2a4-52c2-b59b-52002271d147', 'mobilisation', 'Site Mobilisation, Welfare & Security', 'Pre-construction / Set-up', 'Establish compliant welfare facilities and a secure site boundary in line with CDM 2015 Schedule 2 and the principal contractor''s duties.', 'Children and parents pass the site daily. How do you secure the boundary and provide welfare?', 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('31c0af78-df1c-50f5-b4a2-6f149fecefa4', '6cf91fa9-b4b7-5524-9764-62889d5d79d9', 'Install full-height solid hoarding with anti-climb measures, lockable gates away from the school entrance, CCTV, and welfare cabins with separate site access', 'Prevents children entering and keeps site and school populations apart.', 'Meets CDM 2015 Schedule 2 and safeguarding expectations for work near schools.', 'Solid anti-climb hoarding, segregated gates and CCTV are essential where children are present daily.', 10, -12, true, '{"add":["hoarding","security_gate","cctv","welfare_unit","site_office"],"note":"Anti-climb hoarding, segregated access."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('53fd2369-67df-58be-974a-8b53e64bd895', '6cf91fa9-b4b7-5524-9764-62889d5d79d9', 'Erect timber hoarding but share the existing school gate for site access at agreed times', 'Boundary is solid but shared access creates child/vehicle conflict.', 'Partially compliant — shared access undermines segregation.', 'Site traffic must not share an entrance used by children even at staggered times.', 5, -3, false, '{"add":["hoarding","welfare_unit"],"note":"Shared gate with school."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('2d09b188-f6c8-58f6-8b69-cf888946984f', '6cf91fa9-b4b7-5524-9764-62889d5d79d9', 'Use Heras fencing with privacy netting and rely on supervision to keep children out', 'Fencing is easily breached by children; serious safeguarding risk.', 'Breaches CDM 2015 and safeguarding duties.', 'Mesh fencing is inadequate next to an occupied school and invites unauthorised access.', -3, 12, false, '{"add":["heras_fencing"],"note":"Mesh fence next to school."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('71b00788-db25-5606-82f2-dc58c3e64237', '702a4014-c2a4-52c2-b59b-52002271d147', 'logistics', 'Site Logistics & Traffic Management', 'Set-up', 'Segregate vehicles from pedestrians and plan safe access, egress and deliveries (HSG144 principles).', 'Deliveries must arrive without crossing paths with children at drop-off and pick-up. What is your plan?', 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a72a4d4f-149a-5875-8fe1-0548c616eec0', '71b00788-db25-5606-82f2-dc58c3e64237', 'Agree a delivery management plan banning deliveries during drop-off/pick-up windows, with a dedicated site entrance, banksman and segregated pedestrian routes', 'Removes vehicle/child conflict entirely at peak times.', 'Aligns with HSG144 and safeguarding; timing controls are enforceable.', 'Curfewed deliveries plus a separate entrance and marshalling protect children at the most dangerous times.', 10, -12, true, '{"add":["vehicle_route","pedestrian_route","banksman","signage","wheel_wash"],"note":"Curfewed deliveries, dedicated gate."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('f5371497-af28-53b0-8db2-80ac87670cca', '71b00788-db25-5606-82f2-dc58c3e64237', 'Schedule most deliveries outside school hours but accept some during the day with a marshal', 'Reduces but does not remove daytime conflict.', 'Partially compliant — any delivery during peak windows is a risk.', 'A marshal helps, but deliveries should be fully excluded during drop-off and pick-up.', 5, -3, false, '{"add":["vehicle_route","banksman","signage"],"note":"Partial delivery curfew."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('b13627bd-a8cd-577d-832c-54f272a0d538', '71b00788-db25-5606-82f2-dc58c3e64237', 'Let deliveries arrive whenever suppliers can make it and manage on the day', 'Vehicles and children sharing space at peak times.', 'Breaches traffic management and safeguarding duties.', 'Uncontrolled deliveries near a live school gate are a foreseeable and serious danger to children.', -3, 12, false, '{"add":["vehicle_route"],"note":"Uncontrolled deliveries."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('5ff1f1ef-d3bd-59d5-8b88-c889d2805931', '702a4014-c2a4-52c2-b59b-52002271d147', 'groundworks', 'Excavations & Temporary Works', 'Substructure', 'Prevent excavation collapse and control temporary works under BS 5975 with a Temporary Works Coordinator.', 'Foundations and drainage need excavation close to the site boundary with the live school. How do you control it?', 2);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('ee0e656b-bf85-570f-acdf-f1a75ea0138b', '5ff1f1ef-d3bd-59d5-8b88-c889d2805931', 'Use a permit-to-dig with services scanned, designed trench support, edge protection and barriered exclusion zones, inspected daily by a competent person', 'Prevents collapse and keeps open excavations away from children.', 'Meets CDM 2015, BS 5975 and HSG47.', 'Open excavations near a school must be supported, fenced and inspected, with services located first.', 10, -12, true, '{"add":["excavation_support","exclusion_zone","edge_protection","signage"],"note":"Supported, fenced excavations."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('8e8c4810-199a-59c3-9409-678d9f678759', '5ff1f1ef-d3bd-59d5-8b88-c889d2805931', 'Trench-box the deeper runs and barrier off open excavations at the end of each day', 'Reasonable support but daytime open edges remain a risk.', 'Partially compliant — exclusion should be continuous, not end-of-day only.', 'Open excavations need protecting throughout the day, not just when the team leaves.', 5, -3, false, '{"add":["trench_box","exclusion_zone"],"note":"End-of-day barriers only."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('e7a6a60b-fe47-5b7c-baac-90937d64e5d4', '5ff1f1ef-d3bd-59d5-8b88-c889d2805931', 'Dig and backfill quickly each day, leaving faces unsupported while open', 'Collapse risk and unguarded edges near children.', 'Breaches CDM 2015 and BS 5975.', 'Speed does not justify unsupported excavations, especially adjacent to a school.', -3, 12, false, '{"add":[],"note":"Unsupported open excavations."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('0e1ca9db-984c-51e8-afb1-091c9143a582', '702a4014-c2a4-52c2-b59b-52002271d147', 'height', 'Work at Height & Access', 'Superstructure', 'Select and control safe access for work at height following the Work at Height Regulations 2005 hierarchy.', 'The frame and pitched roof require work at height near the boundary. How is access controlled?', 3);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('712e2a8b-8a1c-596c-8443-fb44ab07d5f7', '0e1ca9db-984c-51e8-afb1-091c9143a582', 'Erect a tied, inspected scaffold with double guardrails, toe boards and brick guards, plus roof edge protection and netting, with no work over the boundary line', 'Collective protection and no dropped-object risk to the school side.', 'Meets WAHR 2005 and the 7-day inspection regime.', 'Scaffold with collective protection and debris control is the right approach near an occupied building.', 10, -12, true, '{"add":["scaffold","edge_protection","signage"],"note":"Tied scaffold with edge/debris protection."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('fcea0d06-463a-5666-b2eb-6474475ccf5a', '0e1ca9db-984c-51e8-afb1-091c9143a582', 'Use MEWPs for the frame and a scaffold only at the roof, with harnesses as backup', 'Acceptable but MEWP positioning near the boundary needs care.', 'Compliant with controls; mixed methods need clear planning.', 'MEWPs are fine away from the boundary; collective protection should still lead at the roof.', 5, -3, false, '{"add":["mewp","edge_protection"],"note":"Mixed MEWP/scaffold access."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('12dbb44f-3e4f-56a5-8631-47c1265219f6', '0e1ca9db-984c-51e8-afb1-091c9143a582', 'Have roofers use ladders and roof ladders with a lanyard where anchors exist', 'High fall and dropped-object risk near children.', 'Breaches WAHR 2005.', 'Ladder-based roof work without collective protection is unsafe and indefensible next to a school.', -3, 12, false, '{"add":[],"note":"Ladder roof access."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('0b863f8d-390d-5859-8de6-7368e591945a', '702a4014-c2a4-52c2-b59b-52002271d147', 'lifting', 'Lifting Operations & Plant', 'Superstructure', 'Plan and supervise lifting operations under LOLER 1998 / PUWER 1998 with a competent Appointed Person.', 'Steel frame members and roof trusses need lifting near the boundary. How do you plan lifts?', 4);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('49060416-b120-5ef2-9d7b-0b8c73d2b4b9', '0b863f8d-390d-5859-8de6-7368e591945a', 'Use a mobile crane with an Appointed Person, lift plan, validated ground bearing, exclusion zones excluding the school side, and lifts only outside school hours where over-boundary risk exists', 'Keeps suspended loads away from children and staff.', 'Meets LOLER 1998 and BS 7121.', 'Planned lifts with exclusion zones and timing controls protect the adjacent school during lifting.', 10, -12, true, '{"add":["mobile_crane","exclusion_zone","banksman","signage"],"note":"Planned lifts, school-side excluded."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a4c9d3c0-3e02-5b13-b76c-bb80f3cb4200', '0b863f8d-390d-5859-8de6-7368e591945a', 'Use a telehandler and crane with a banksman and cordon the immediate lift area', 'Local control but no formal lift plan or timing strategy.', 'Partially compliant — an AP and written plan are expected.', 'Cordoning the lift area helps but a documented plan and AP are still required.', 5, -3, false, '{"add":["mobile_crane","exclusion_zone"],"note":"Cordon only; no formal plan."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('1eef77b3-9bc0-586e-917f-09713fb18e79', '0b863f8d-390d-5859-8de6-7368e591945a', 'Lift members as the steel arrives and keep the team clear by shouting warnings', 'Suspended loads near an occupied school with no planning.', 'Serious breach of LOLER/BS 7121.', 'Unplanned lifting beside a live school is an unacceptable risk to children and workers.', -3, 12, false, '{"add":["mobile_crane"],"note":"Unplanned lifting."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('43fc2be1-780c-5c40-874a-ce1ea7bb9e10', '702a4014-c2a4-52c2-b59b-52002271d147', 'systems', 'Safe Systems: RAMS, Permits, ITPs & Emergency Planning', 'Throughout construction', 'Implement risk assessments and method statements, permits-to-work, inspection & test plans and emergency arrangements.', 'How will you run safe systems, safeguarding and emergencies alongside a live school?', 5);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('0b11202f-8350-5b09-b7dd-6d8882b068bc', '43fc2be1-780c-5c40-874a-ce1ea7bb9e10', 'Brief task RAMS, operate permits for high-risk work, keep an ITP, brief all staff on safeguarding (DBS, no contact with pupils), and agree a joint emergency/evacuation plan with the school', 'Controls tasks and protects children; emergencies are coordinated.', 'Meets CDM 2015, MHSWR and safeguarding obligations.', 'Working beside a school adds safeguarding and joint emergency planning to the standard safe-system regime.', 10, -12, true, '{"add":["fire_point","first_aid","signage"],"note":"RAMS, permits, ITP, safeguarding, joint emergency plan."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('608c632e-4bc8-58ab-a010-6d509a23c9f1', '43fc2be1-780c-5c40-874a-ce1ea7bb9e10', 'Use a standard induction with a safeguarding mention and the contractor''s generic emergency plan', 'Baseline only; safeguarding and coordination are thin.', 'Partially compliant — safeguarding near schools needs more rigour.', 'A passing mention of safeguarding is insufficient where children are present daily.', 5, -3, false, '{"add":["first_aid"],"note":"Generic systems, light safeguarding."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('cbb56be6-e416-5cc1-802c-b0f24a6605ef', '43fc2be1-780c-5c40-874a-ce1ea7bb9e10', 'Rely on the fence to keep children out and deal with safety matters as they come up', 'No structured task control or safeguarding regime.', 'Breaches CDM 2015 and safeguarding duties.', 'A fence alone is not a safe system of work, and safeguarding cannot be left to chance.', -3, 12, false, '{"add":[],"note":"No formal systems."}'::jsonb, 2);
insert into scenarios (id, slug, title, sector, difficulty, summary, description, image_key, is_published, sort_order) values ('b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'housing-development', 'Residential Housing Development', 'Residential', 'foundation', 'A greenfield housing development of multiple plots with groundworks, timber-frame erection and high delivery volumes.', 'You are setting up a residential development of detached and terraced homes across several plots. The work includes drainage and foundations, timber-frame and roof erection, and frequent material deliveries on shared estate roads. Early plots will be occupied while later plots are still under construction, so public interface grows over time.', 'housing', true, 3);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('4398d819-9e3b-58a4-8f9b-53afff6088a6', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'mobilisation', 'Site Mobilisation, Welfare & Security', 'Pre-construction / Set-up', 'Establish compliant welfare facilities and a secure site boundary in line with CDM 2015 Schedule 2 and the principal contractor''s duties.', 'How do you set up the compound, welfare and site security on the greenfield plot?', 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('4d9b5a89-ab62-592d-b0b2-a9a8e4b412bb', '4398d819-9e3b-58a4-8f9b-53afff6088a6', 'Establish a central compound with Heras fencing on a secure perimeter, welfare cabins (toilets, canteen, drying room) sized for the workforce, signage and a controlled single entrance', 'Secure perimeter and proper welfare from the start.', 'Meets CDM 2015 Schedule 2 welfare duties.', 'Even on greenfield sites a secure perimeter and full welfare must be in place before work begins.', 10, -12, true, '{"add":["heras_fencing","security_gate","welfare_unit","site_office","signage"],"note":"Secure compound with welfare."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('06f73b64-88fb-56b5-b948-ac8ead2035cd', '4398d819-9e3b-58a4-8f9b-53afff6088a6', 'Bring welfare cabins but leave the perimeter open where it backs onto fields', 'Welfare is fine but an open perimeter invites trespass.', 'Partially compliant — the site must be secured against unauthorised access.', 'Open boundaries risk public and child access, theft and vandalism, even in rural settings.', 5, -3, false, '{"add":["welfare_unit","site_office"],"note":"Welfare provided, perimeter open."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('45a16379-83cf-5a6e-9399-57bb7244211e', '4398d819-9e3b-58a4-8f9b-53afff6088a6', 'Start the show-home plot first and add welfare and fencing once the team is established', 'Workforce without facilities and an unsecured site.', 'Breaches CDM 2015 welfare duties.', 'Welfare and security are prerequisites, not later additions.', -3, 12, false, '{"add":[],"note":"No welfare or security at start."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('b833c7c5-5631-575d-839d-7af5630acdfd', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'logistics', 'Site Logistics & Traffic Management', 'Set-up', 'Segregate vehicles from pedestrians and plan safe access, egress and deliveries (HSG144 principles).', 'Estate roads carry both deliveries and (later) residents. How do you manage traffic and pedestrians?', 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('40c36a0e-e2de-5470-87d4-2072e18e0dce', 'b833c7c5-5631-575d-839d-7af5630acdfd', 'Operate a logistics plan with a delivery booking system, banksman, signed haul routes, a wheel-wash, speed limits, and physical segregation of occupied plots from construction traffic', 'Separates residents and pedestrians from site vehicles.', 'Aligns with HSG144 and the duty to protect the public.', 'Booked deliveries, haul routes and segregation of occupied areas are key as the site becomes part-occupied.', 10, -12, true, '{"add":["vehicle_route","pedestrian_route","banksman","wheel_wash","signage"],"note":"Booked deliveries, segregated occupied plots."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a2b9a032-b96e-549d-8246-bb4b35c2b6bb', 'b833c7c5-5631-575d-839d-7af5630acdfd', 'Sign the haul route and ask drivers to keep speeds low around occupied plots', 'Some control but relies on driver behaviour.', 'Partially compliant — physical segregation of residents is expected.', 'Signs and goodwill do not reliably protect residents living among active construction.', 5, -3, false, '{"add":["vehicle_route","signage"],"note":"Signed route, no segregation."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('93914838-8d2a-55bb-b7fd-1eebe8d5c02f', 'b833c7c5-5631-575d-839d-7af5630acdfd', 'Let deliveries find their own way around the plots as access changes day to day', 'Vehicles and residents mixing on shared roads.', 'Breaches traffic management and public-protection duties.', 'Ad-hoc routing around occupied homes endangers residents, especially children.', -3, 12, false, '{"add":["vehicle_route"],"note":"Ad-hoc delivery routing."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('726eac1c-d585-59b4-b009-488696217fa3', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'groundworks', 'Excavations & Temporary Works', 'Substructure', 'Prevent excavation collapse and control temporary works under BS 5975 with a Temporary Works Coordinator.', 'Foundations and deep drainage runs are needed across the plots. How do you control excavations?', 2);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a7bb7009-c0a1-5543-9194-3523239002d0', '726eac1c-d585-59b4-b009-488696217fa3', 'Issue permits-to-dig with services located (CAT/GPR), use trench boxes/shoring for runs over 1.2 m, provide edge protection and barriers, and inspect daily', 'Prevents collapse and service strikes across many small excavations.', 'Meets CDM 2015, BS 5975 and HSG47.', 'Repetitive trenching is a common killer; support, service location and inspection are essential.', 10, -12, true, '{"add":["excavation_support","trench_box","exclusion_zone","edge_protection"],"note":"Permits, support and inspection."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('6611d1c4-1e71-501a-9b73-710b0061a172', '726eac1c-d585-59b4-b009-488696217fa3', 'Use trench boxes on the deep drainage but batter the shallow foundation digs', 'Good for drainage; shallow digs still need attention to ground and edges.', 'Partially compliant — service location and edge protection still required.', 'Even shallow excavations need service checks and edge protection where people pass.', 5, -3, false, '{"add":["trench_box","exclusion_zone"],"note":"Partial support; limited controls."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('c4f22005-aaad-578d-b3bf-2c3c54ca15ce', '726eac1c-d585-59b4-b009-488696217fa3', 'Dig foundations and drainage to vertical faces and work in them briefly to keep pace', 'Trench collapse risk — a leading cause of construction deaths.', 'Breaches CDM 2015 and BS 5975.', 'Entering unsupported trenches, even briefly, has killed many workers; it is never acceptable.', -3, 12, false, '{"add":[],"note":"Unsupported trenches."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('dc69813a-cdd6-5e76-9839-535d969729cf', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'height', 'Work at Height & Access', 'Superstructure', 'Select and control safe access for work at height following the Work at Height Regulations 2005 hierarchy.', 'Timber frames and pitched roofs are erected across the plots. How is work at height managed?', 3);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('09787042-7a5b-5373-a9a0-7e7df6be8b04', 'dc69813a-cdd6-5e76-9839-535d969729cf', 'Use proprietary edge protection systems, tied scaffold for roof works with guardrails and toe boards, safety nets under the roof during erection, and trained operatives', 'Collective protection during the highest-risk roof phase.', 'Meets WAHR 2005; nets provide collective fall arrest.', 'Roof erection is high risk; scaffold, edge protection and safety nets are the standard controls.', 10, -12, true, '{"add":["scaffold","edge_protection","signage"],"note":"Scaffold, edge protection and nets."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('b75aed5b-69d5-5f46-87d2-6ee6bf7c64d5', 'dc69813a-cdd6-5e76-9839-535d969729cf', 'Erect scaffold to the eaves and use harnesses for the roof, with a roof ladder', 'Eaves protection is good but roof work leans on PPE.', 'Acceptable with rescue plan but collective protection is preferred.', 'Harnesses require anchor points and rescue plans; nets/edge protection rank higher.', 5, -3, false, '{"add":["scaffold","edge_protection"],"note":"Scaffold to eaves; PPE on roof."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('2a1901cb-e797-5e95-832d-2ec1ab9adc6b', 'dc69813a-cdd6-5e76-9839-535d969729cf', 'Have the frame and roof crews work off the structure using ladders to access levels', 'Falls during frame and roof erection.', 'Breaches WAHR 2005.', 'Climbing the frame and ladder access for roof work are frequent causes of serious falls.', -3, 12, false, '{"add":[],"note":"Ladder access, no edge protection."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('d787011b-5297-5a27-9b4e-0899c97f45d5', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'lifting', 'Lifting Operations & Plant', 'Superstructure', 'Plan and supervise lifting operations under LOLER 1998 / PUWER 1998 with a competent Appointed Person.', 'Timber-frame panels and roof trusses are delivered and lifted into place. How do you plan lifting?', 4);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('d1e3eca0-b8b9-5f3c-9c31-0c7db13ad32e', 'd787011b-5297-5a27-9b4e-0899c97f45d5', 'Use a lorry-loader/telehandler with trained operators and slingers, a lift plan, exclusion zones, and a banksman, checking ground and proximity to occupied plots', 'Controls panel lifts and keeps residents and workers clear.', 'Meets LOLER 1998 and PUWER 1998.', 'Even routine frame lifts need a plan, competent operators, exclusion zones and ground checks.', 10, -12, true, '{"add":["mobile_crane","exclusion_zone","banksman","signage"],"note":"Planned panel lifts with exclusion zones."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('c40b1d6a-2633-5968-a81b-114f806b158c', 'd787011b-5297-5a27-9b4e-0899c97f45d5', 'Use the delivery lorry''s crane with the driver slinging loads and a spotter nearby', 'Workable but the driver may not be a competent slinger and planning is light.', 'Partially compliant — competence and a lift plan must be assured.', 'Lorry-loader lifts still need competent slinging, planning and exclusion zones.', 5, -3, false, '{"add":["mobile_crane","exclusion_zone"],"note":"Driver-slung loads; light planning."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('a0762502-0f90-5de6-a933-03a8986c219e', 'd787011b-5297-5a27-9b4e-0899c97f45d5', 'Lift panels straight off the lorry near occupied plots without a set exclusion zone', 'Suspended loads over or near residents and workers.', 'Breaches LOLER/PUWER.', 'Unplanned lifting beside occupied homes risks struck-by and dropped-load incidents.', -3, 12, false, '{"add":["mobile_crane"],"note":"Unplanned lifting near homes."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('e4350722-d35d-5859-a332-d3ea0beca06f', 'b13b7c5e-1b12-5f98-ad31-3cea0be8abb7', 'systems', 'Safe Systems: RAMS, Permits, ITPs & Emergency Planning', 'Throughout construction', 'Implement risk assessments and method statements, permits-to-work, inspection & test plans and emergency arrangements.', 'How will you run safe systems, inspections and emergencies across a phased, part-occupied site?', 5);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('638e40cd-b65f-5cdc-b2b3-222f8160193b', 'e4350722-d35d-5859-a332-d3ea0beca06f', 'Brief task RAMS, permits for excavations and lifting, ITPs for foundations and drainage, COSHH controls, and an emergency plan with fire points and first aid covering occupied plots', 'Matches controls to tasks and covers residents in emergencies.', 'Meets CDM 2015, MHSWR and COSHH 2002.', 'A phased, part-occupied site needs task RAMS, permits, ITPs and an emergency plan that includes residents.', 10, -12, true, '{"add":["fire_point","first_aid","signage"],"note":"RAMS, permits, ITP, emergency plan."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('97832102-3b52-5325-9d2d-a4ce92e49ce1', 'e4350722-d35d-5859-a332-d3ea0beca06f', 'Run a standard induction and a generic risk assessment covering the whole site', 'Baseline only; misses task and occupancy-specific risks.', 'Partially compliant — RAMS must be task-specific.', 'Generic documents do not address the changing risks of a phased, occupied development.', 5, -3, false, '{"add":["first_aid"],"note":"Generic risk assessment."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('75adfe27-23f0-59c7-8c89-a71cd9ceea70', 'e4350722-d35d-5859-a332-d3ea0beca06f', 'Keep things flexible and brief the team verbally each morning', 'No documented control or emergency preparedness.', 'Breaches CDM 2015 and MHSWR.', 'Verbal-only briefings are not a safe system of work and leave emergencies unplanned.', -3, 12, false, '{"add":[],"note":"Verbal briefings only."}'::jsonb, 2);
insert into scenarios (id, slug, title, sector, difficulty, summary, description, image_key, is_published, sort_order) values ('a0e14ac3-7220-5014-a26b-2073b89334ec', 'distribution-warehouse', 'Distribution Warehouse', 'Industrial', 'intermediate', 'A large-footprint distribution warehouse with piled foundations, a steel portal frame, cladding at height and MEWP access.', 'You are managing construction of a large distribution centre. The works include piling and ground-bearing slabs, erection of a tall steel portal frame, roof and wall cladding using MEWPs, and significant plant movements across an open site. Scale, simultaneous trades and work at height dominate the risk picture.', 'warehouse', true, 4);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('77555649-e606-5ba2-9bb0-ae7c719a9562', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'mobilisation', 'Site Mobilisation, Welfare & Security', 'Pre-construction / Set-up', 'Establish compliant welfare facilities and a secure site boundary in line with CDM 2015 Schedule 2 and the principal contractor''s duties.', 'On a large open plot, how do you establish the boundary, welfare and security?', 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('fc9ca217-6d21-587c-8dd7-5ef1fc4f3960', '77555649-e606-5ba2-9bb0-ae7c719a9562', 'Secure the full perimeter with fencing and lockable gates, provide a welfare village (toilets, canteen, drying rooms) scaled for a large workforce, a site office, signage and CCTV', 'Controls access to a large site and supports a big workforce.', 'Meets CDM 2015 Schedule 2 for the planned numbers.', 'Large sites need a fully secured perimeter and welfare scaled to the peak workforce from the outset.', 10, -12, true, '{"add":["heras_fencing","security_gate","welfare_unit","site_office","cctv","material_storage"],"note":"Full perimeter, welfare village."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('1bd62981-767a-5d9d-b676-b515241119d9', '77555649-e606-5ba2-9bb0-ae7c719a9562', 'Fence the active working zone now and extend the perimeter as the build spreads out', 'Active area secured but the wider plot is exposed.', 'Partially compliant — the whole site under your control must be secured.', 'Leaving large areas of the site unsecured invites unauthorised access and plant theft.', 5, -3, false, '{"add":["heras_fencing","welfare_unit","site_office"],"note":"Partial perimeter only."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('88b426ff-f0c1-55eb-b057-c0d8ca3bc00d', '77555649-e606-5ba2-9bb0-ae7c719a9562', 'Rely on the site''s distance from the public and minimal welfare until numbers build', 'Workforce without adequate facilities; site insecure.', 'Breaches CDM 2015 welfare duties.', 'Remoteness does not remove the duty to secure the site and provide proper welfare.', -3, 12, false, '{"add":[],"note":"Minimal welfare and security."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('30890af1-d7a4-5c6a-a18a-af51106ae232', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'logistics', 'Site Logistics & Traffic Management', 'Set-up', 'Segregate vehicles from pedestrians and plan safe access, egress and deliveries (HSG144 principles).', 'Heavy plant and deliveries move across a large open site alongside trades on foot. How do you manage it?', 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('5671f8a9-4f0c-5ffd-88e0-76f1baf5895c', '30890af1-d7a4-5c6a-a18a-af51106ae232', 'Establish one-way haul roads, segregated pedestrian walkways, designated laydown areas, a banksman regime, speed limits and a wheel-wash, reviewed as the build progresses', 'Separates plant from people across a busy, changing site.', 'Aligns with HSG144 and workplace transport guidance.', 'On large plant-heavy sites, segregated routes, laydown discipline and marshalling prevent struck-by incidents.', 10, -12, true, '{"add":["vehicle_route","pedestrian_route","one_way_system","banksman","wheel_wash","lay_down_area","signage"],"note":"Segregated haul roads and walkways."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('ef39c6ad-7f84-509a-ab01-f41ff84dc2b9', '30890af1-d7a4-5c6a-a18a-af51106ae232', 'Mark walking routes with cones and brief plant operators to watch for pedestrians', 'Some demarcation but relies on operator vigilance.', 'Partially compliant — physical segregation is preferred.', 'Cones and briefings are weaker than defined, segregated routes on a large plant site.', 5, -3, false, '{"add":["vehicle_route","pedestrian_route","signage"],"note":"Cone-marked routes."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('7e8c8e22-3c33-56cb-b553-706fceddada9', '30890af1-d7a4-5c6a-a18a-af51106ae232', 'Let plant and people share the open site and manage interactions informally', 'High struck-by risk from plant movements.', 'Breaches workplace transport and CDM duties.', 'Mixing plant and pedestrians without segregation is a leading cause of serious site injuries.', -3, 12, false, '{"add":["vehicle_route"],"note":"No segregation of plant and people."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('455e8218-1ec7-502c-9817-da6dc8ec75cc', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'groundworks', 'Excavations & Temporary Works', 'Substructure', 'Prevent excavation collapse and control temporary works under BS 5975 with a Temporary Works Coordinator.', 'The frame sits on piled foundations across the footprint. How do you control piling and excavation?', 2);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('8f136c2e-e2b7-5777-9ba1-cb4255d33783', '455e8218-1ec7-502c-9817-da6dc8ec75cc', 'Use a piling mat designed and certified (e.g. to BRE 470) with a TWC, exclusion zones around rigs, service location, and inspection of mats and excavations', 'Prevents rig overturn and collapse; keeps people clear of rigs.', 'Meets BS 5975, CDM 2015 and HSG47; piling mats per BRE 470.', 'Piling rigs must work off a designed, certified mat with exclusion zones — overturns are catastrophic.', 10, -12, true, '{"add":["excavation_support","exclusion_zone","signage","material_storage"],"note":"Certified piling mat, rig exclusion zones."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('17faf421-136a-5488-8f81-82f4fcb8b6f1', '455e8218-1ec7-502c-9817-da6dc8ec75cc', 'Lay a granular working platform by experience and keep people back from the rigs', 'Better than nothing but an unverified platform may fail under the rig.', 'Partially compliant — the platform should be designed and certified.', 'Working platforms for piling rigs must be engineered and signed off, not judged by eye.', 5, -3, false, '{"add":["exclusion_zone","signage"],"note":"Uncertified working platform."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('3f4b3063-7eb2-5a32-8a13-0ac5cd402de3', '455e8218-1ec7-502c-9817-da6dc8ec75cc', 'Track the piling rig straight onto the formation and pile as the ground allows', 'Rig overturn risk on inadequate ground.', 'Breaches BS 5975 and CDM 2015.', 'Operating heavy piling rigs without a designed platform is a known cause of fatal overturns.', -3, 12, false, '{"add":[],"note":"No designed piling platform."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('8e2c2ba4-b258-5688-803d-4a82c6325138', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'height', 'Work at Height & Access', 'Superstructure', 'Select and control safe access for work at height following the Work at Height Regulations 2005 hierarchy.', 'Tall steel frame, roof and wall cladding require work at height across a big footprint. How is access controlled?', 3);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('ac30b622-2a6e-5fbf-b0ec-a47ebde15240', '8e2c2ba4-b258-5688-803d-4a82c6325138', 'Use MEWPs matched to the task with trained operators, harness/restraint where specified, exclusion zones beneath, rescue plans, and edge protection / nets on the roof', 'Provides safe access and arrests falls on the roof.', 'Meets WAHR 2005; MEWP operators trained (e.g. IPAF), rescue planned.', 'Large cladding/roof works are typically MEWP-led with collective roof protection and rescue arrangements.', 10, -12, true, '{"add":["mewp","edge_protection","exclusion_zone","signage"],"note":"MEWP access with roof nets/edge protection."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('ccd841a2-0181-52f0-9993-4f021b0822f8', '8e2c2ba4-b258-5688-803d-4a82c6325138', 'Use MEWPs for cladding and scaffold towers at the gable ends, harnesses on the roof', 'Reasonable but roof work leans on PPE without nets.', 'Acceptable with rescue plan; collective protection preferred on the roof.', 'MEWPs and towers are valid; the roof phase should still prioritise nets/edge protection.', 5, -3, false, '{"add":["mewp","edge_protection"],"note":"MEWP/tower mix; PPE on roof."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('78ae5433-d7c6-5497-818b-f8733f3f0e57', '8e2c2ba4-b258-5688-803d-4a82c6325138', 'Erect the frame and clad using ladders and the steelwork itself for access', 'Severe fall risk on a tall frame.', 'Breaches WAHR 2005.', 'Climbing steel and using ladders for tall cladding work is extremely dangerous and non-compliant.', -3, 12, false, '{"add":[],"note":"Ladder/steel-climbing access."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('71ca8af6-a96b-527c-a4f0-98385bdf586d', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'lifting', 'Lifting Operations & Plant', 'Superstructure', 'Plan and supervise lifting operations under LOLER 1998 / PUWER 1998 with a competent Appointed Person.', 'Steel portal frame members are lifted by mobile crane across the site. How do you plan the lifts?', 4);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('23530fe6-e5ba-5326-b9f6-1d550c3f62bc', '71ca8af6-a96b-527c-a4f0-98385bdf586d', 'Appoint an Appointed Person, produce lift plans per area, validate ground bearing for crane outriggers, set exclusion zones, use trained slingers/signallers and coordinate with other trades', 'Controls heavy steel lifts amid simultaneous trades.', 'Meets LOLER 1998 and BS 7121.', 'Repeated heavy lifts across a busy site need an AP, area lift plans, ground validation and trade coordination.', 10, -12, true, '{"add":["mobile_crane","exclusion_zone","banksman","signage"],"note":"Area lift plans with exclusion zones."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('25639c7b-8c77-541d-86e9-d3e12e416f16', '71ca8af6-a96b-527c-a4f0-98385bdf586d', 'Use a competent crane crew with a standard lift plan and outrigger mats', 'Competent crew but coordination with other trades is informal.', 'Partially compliant — area-specific plans and coordination expected.', 'Standard plans miss the coordination needed where many trades work beneath lifts.', 5, -3, false, '{"add":["mobile_crane","exclusion_zone"],"note":"Standard plan; informal coordination."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('9f740b7d-e273-590e-b19f-093314ddea87', '71ca8af6-a96b-527c-a4f0-98385bdf586d', 'Lift steel as it arrives and keep other trades working in the same area to hold the programme', 'Loads over working trades; struck-by and dropped-load risk.', 'Breaches LOLER/BS 7121.', 'Lifting over working people to protect the programme is a classic, dangerous false economy.', -3, 12, false, '{"add":["mobile_crane"],"note":"Lifting over working trades."}'::jsonb, 2);
insert into stages (id, scenario_id, key, title, phase, learning_outcome, prompt, sort_order) values ('e7993dac-14de-553f-bede-6d425c65f397', 'a0e14ac3-7220-5014-a26b-2073b89334ec', 'systems', 'Safe Systems: RAMS, Permits, ITPs & Emergency Planning', 'Throughout construction', 'Implement risk assessments and method statements, permits-to-work, inspection & test plans and emergency arrangements.', 'How will you run safe systems, inspection regimes and emergencies on a large multi-trade site?', 5);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('e35695c9-7603-5335-8c81-194a8ceb6da2', 'e7993dac-14de-553f-bede-6d425c65f397', 'Operate task RAMS, permits for piling/lifting/hot works, ITPs for piling, slab and frame, daily coordination of simultaneous operations, and an emergency plan with fire points, first aid and rescue', 'Controls each task and the interfaces between trades.', 'Meets CDM 2015 and MHSWR; ITPs assure quality holds.', 'Large multi-trade sites need permits, ITPs, daily SIMOPS coordination and a tested emergency plan.', 10, -12, true, '{"add":["fire_point","first_aid","signage"],"note":"RAMS, permits, ITP, SIMOPS coordination."}'::jsonb, 0);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('d872fbcb-7c52-5bbf-90e1-22ab3fc464c8', 'e7993dac-14de-553f-bede-6d425c65f397', 'Use task RAMS and a standard emergency plan but coordinate trades only at weekly meetings', 'Good documents but weak day-to-day interface control.', 'Partially compliant — simultaneous operations need closer coordination.', 'Weekly coordination is too coarse where many trades share space daily.', 5, -3, false, '{"add":["first_aid"],"note":"Weekly-only coordination."}'::jsonb, 1);
insert into decisions (id, stage_id, choice_text, safety_impact, legal_impact, explanation, score_effect, risk_effect, is_ideal, layout_effect, sort_order) values ('04d62b8e-3d68-5a31-9e6a-be787c09a3e1', 'e7993dac-14de-553f-bede-6d425c65f397', 'Issue generic RAMS and let supervisors sort out clashes between trades as they happen', 'Uncontrolled interfaces between high-risk activities.', 'Breaches CDM 2015 and MHSWR.', 'Leaving high-risk interfaces to chance on a large site invites serious incidents.', -3, 12, false, '{"add":[],"note":"Generic RAMS, no coordination."}'::jsonb, 2);
